"use strict";
var _demo = await jitiImport("../src/data/demo");
var _demoEval = await jitiImport("../src/lib/demoEval");
var _demoGeometry = await jitiImport("../src/lib/demoGeometry"); // Run: npx jiti scripts/demo-check.ts


const rows = _demo.demoSteps.flatMap((s) => s.data.kind === 'feedback' ? s.data.rows : []);
const run = (o = {}) =>
(0, _demoEval.evaluate)({ scenario: 'attack', threshold: _demo.demoModel.defaultThreshold, rules: { ..._demo.defaultRules, ...Object.fromEntries((o.off ?? []).map((r) => [r, false])) }, ...o }, rows);
const ok = (cond, msg) => {
  if (!cond) throw new Error(`FAIL: ${msg}`);
};

const full = run();
ok(full.jev.score === 0.97 && full.jev.confidence === 0.91, `default JEV output, got ${full.jev.score}/${full.jev.confidence}`);
ok(full.verdict === 'block' && !full.missed, 'default attack is blocked');
ok(full.feedback.find((f) => f.target)?.endpoint === 'POST /adminer/', 'feedback targets POST /adminer/');
const t = full.feedback.find((f) => f.target)?.series ?? [];
ok(t[5] > t[4] * 10 && t[10] < t[5], 'sampling rate jumps then cools');

ok(run({ threshold: 0.99 }).verdict === 'allow', 'threshold above the score lets it through');
ok(run({ off: ['serializedObject', 'classAllowList', 'maxBody'] }).jev.reason === 'sampled', 'risk:high still samples a quiet attack');
const blind = run({ off: ['serializedObject', 'classAllowList', 'maxBody', 'riskHigh'] });
ok(!blind.jev.called && blind.missed, 'no rules, no sampling → attack forwarded unseen');
ok(blind.feedback.find((f) => f.target)?.series[5] === 0.01, 'a missed attack teaches the loop nothing');
ok(run({ off: ['serializedObject'] }).checks.find((c) => c.id === 'malicious-input')?.detail.includes('Monolog'), 'class rule reports its own finding');

const benign = run({ scenario: 'benign', threshold: 0.3 });
ok(!benign.jev.called && benign.verdict === 'allow' && benign.suspicion === 0, 'benign takes the cheap path at any threshold');

for (const s of _demo.demoSteps) {
  for (const id of s.highlightEdges) ok(_demo.demoEdges.some((e) => e.id === id), `${s.id}: unknown edge ${id}`);
  for (const id of s.highlightNodes) ok(_demo.demoNodes.some((n) => n.id === id), `${s.id}: unknown node ${id}`);
  for (const v of [s, ...Object.values(s.alt ?? {})]) {
    for (const id of v.highlightEdges ?? []) ok(_demo.demoEdges.some((e) => e.id === id), `${s.id}: unknown alt edge ${id}`);
    if (v.packet) ok((0, _demoGeometry.packetPath)(v.packet).length > 1, `${s.id}: no route ${v.packet.from} → ${v.packet.to}`);
  }
}
